import org.jetbrains.kotlin.gradle.dsl.JvmTarget

plugins {
    id("com.android.library") version "8.10.1"
    kotlin("android") version "2.1.21"
}

val repository = rootDir.resolve("../..")
// generated by scripts/bindings.sh kotlin
val bindings = repository.resolve("dist/bindings/kotlin")
// built by scripts/build.sh android: Rust target -> Android ABI
val abis = mapOf(
    "aarch64-linux-android" to "arm64-v8a",
    "armv7-linux-androideabi" to "armeabi-v7a",
    "i686-linux-android" to "x86",
    "x86_64-linux-android" to "x86_64",
)
val jniLibsDir = layout.buildDirectory.dir("jniLibs")

android {
    namespace = "com.crypt0p1a.kraken"
    compileSdk = 35

    defaultConfig {
        minSdk = 24
        testInstrumentationRunner = "androidx.test.runner.AndroidJUnitRunner"
        consumerProguardFiles("consumer-rules.pro")
    }

    sourceSets {
        getByName("main") {
            java.srcDir(bindings)
            jniLibs.srcDir(jniLibsDir)
        }
        // the tests of the JVM, run on the device
        getByName("androidTest") {
            java.srcDir(rootDir.resolve("../kotlin/src/test/kotlin"))
        }
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }

    packaging {
        resources.excludes += setOf("META-INF/LICENSE*", "META-INF/AL2.0", "META-INF/LGPL2.1")
    }
}

kotlin {
    compilerOptions {
        jvmTarget.set(JvmTarget.JVM_17)
    }
}

dependencies {
    implementation("net.java.dev.jna:jna:5.17.0@aar")
    implementation("org.jetbrains.kotlinx:kotlinx-coroutines-core:1.10.2")

    androidTestImplementation("androidx.test:runner:1.6.2")
    androidTestImplementation("junit:junit:4.13.2")
    androidTestImplementation("org.jetbrains.kotlinx:kotlinx-coroutines-test:1.10.2")
    androidTestImplementation("com.squareup.okhttp3:mockwebserver:4.12.0")
}

/** libkraken_ffi.so of each ABI, from dist/<target> */
val copyJniLibs by tasks.registering(Sync::class) {
    abis.forEach { (target, abi) ->
        from(repository.resolve("dist/$target")) {
            include("libkraken_ffi.so")
            into(abi)
        }
    }
    into(jniLibsDir)
    doFirst {
        check(bindings.resolve("uniffi").isDirectory) {
            "no bindings in $bindings: run scripts/bindings.sh kotlin"
        }
        val missing = abis.keys.filterNot { repository.resolve("dist/$it/libkraken_ffi.so").isFile }
        check(missing.size < abis.size) { "no Android library in dist/: run scripts/build.sh android" }
        if (missing.isNotEmpty()) logger.warn("kraken-android: no library for $missing")
    }
}

tasks.named("preBuild") {
    dependsOn(copyJniLibs)
}
